    "word": "Процесс",
    "created_at": "2026-03-19T23:48:42.670",
    "updated_at": "2026-04-26T21:03:12.260",
    "is_active": true,
    "is_hard": true,
    "is_learned": true,
    "definition": "Процесс = действие, которое длится во времени (не моментально, не одним щелчком).",
    "example": "Три простых признака процесса:\r\nЕсть начало.\r\nЕсть середина (что-то происходит).\r\nЕсть конец (результат).\r\n\r\nПримеры из жизни (простые)\r\nПриготовление супа — это процесс (нужно почистить, порезать, сварить, посолить).\r\nУчёба в колледже — это длинный процесс (4 года).\r\nКак ты учишь русский — это процесс (каждый день новое слово).\r\nДыхание — это непрерывный процесс (даже когда ты спишь).",
    "language": "ru",
    "image": "",
    "repetition_count": 0,
    "next_review_date": null
