{
  "model": "training.word",
  "pk": 435,
  "fields": {
    "user": 1,
    "word": "Пнуть, пни, пинать, пинок",
    "created_at": "2026-03-19T23:48:42.670",
    "updated_at": "2026-04-04T00:10:59.058",
    "is_active": false,
    "is_hard": false,
    "is_learned": false,
    "definition": "Это вся семья слов про удар ногой.",
    "example": "Слово\tЗначение\tПример\r\nПнуть\tУдарить ногой 1 раз (сделать одно действие).\tФутболист хотел пнуть мяч, но промахнулся.\r\nПни\tКоманда: «Сделай это!» (ты пни).\tПни эту коробку ногой, она мешает.\r\nПинать\tУдарять ногой много раз или постоянно (процесс).\tНе пинай стул, ты его сломаешь.\r\nПинок\tСуществительное (один удар ногой).\tКот получил пинок и убежал.",
    "language": "ru",
    "image": "images/i_j99HO4o.jpg",
    "repetition_count": 0,
    "next_review_date": null
  }
},
{
  "model": "training.word",
  "pk": 436,
