    "is_learned": false,
    "definition": "Поколение людей, которые родились примерно с 1981 по 1996 год (выросли при компьютерах и интернете, но помнят жизнь без смартфонов).",
    "example": "Пример: Мои старшие братья — миллениалы, они помнят, как слушали музыку на кассетах.\r\nПример: Миллениалы любят путешествовать и ценят свободу.",
