{
  "model": "training.word",
  "pk": 437,
  "fields": {
    "user": 1,
    "word": "Пни, пенёк, пень",
    "created_at": "2026-03-19T23:48:42.670",
    "updated_at": "2026-04-04T00:08:43.245",
    "is_active": false,
    "is_hard": false,
    "is_learned": false,
    "definition": "Это три формы одного слова «пень» (оставшаяся нижняя часть срубленного дерева).",
    "example": "Слово\tКраткое значение\tПример\r\nПень\tЧто? (сам предмет). Я вижу один пень.\tВ лесу стоял старый сухой пень.\r\nПня\tКого? Чего? (нет чего). Родительный падеж.\tНа лесной дороге не было ни одного пня.\r\nПеньки\tМного маленьких пней. Уменьшительная форма.\tДети сидели на маленьких пеньках у костра.\r\nВажно: «Пни» — это форма для команды (повелительное наклонение от глагола «пнуть»), не путайте с «пень».",
    "language": "ru",
    "image": "",
    "repetition_count": 0,
    "next_review_date": null
  }
},
